'use strict';
const assert=require('node:assert/strict');
const {cohort,validateDeclaration,assertActualCalls}=require('./csrfIndirectChainEvidence');
function assertDefendedActivity(before,after){
 const priorIds=new Set(before.entries.map(x=>x.id));
 const added=after.entries.filter(x=>!priorIds.has(x.id)&&/rag/.test(x.name));
 assert.equal(added.length,1,'Exactly one new gadget activity required');
 assert.equal(added[0].flag,'warning');assert.equal(added[0].success,false);
 return added[0];
}
async function runIndirectChain({origin,student,sibling,password,root,identity,documentEvidenceReader,progress,state,transport}){
 validateDeclaration();const evidence=require('./csrfIndirectChainEvidence').createIndirectEvidence({identity,documentEvidenceReader,progress,student,sibling,state,root,model:transport.model});const result={status:'running',scope:'Actual durable retrieval/model summary + lab server gadget interpreter; no independent browser effect',cases:[],declaredActorCases:['clean-Q1','off-topic','on-topic-first','same-query-replay','on-topic-second','defended-second-query'],actualModelCalls:0};
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(Error('Indirect cohort deadline')),1200000);const save=()=>{result.actualModelCalls=transport.calls.length;result.notAttemptedActorCases=result.declaredActorCases.filter(name=>!result.cases.some(c=>c.name===name));evidence.save('csrf-indirect-result',result);};
 async function login(user){const cookies=new Map();let token;async function request(route,body){controller.signal.throwIfAborted();const r=await fetch(origin+route,{method:body===undefined?'GET':'POST',headers:{'content-type':'application/json',origin,...(token?{authorization:'Bearer '+token}:{}),...(cookies.size?{cookie:[...cookies].map(([k,v])=>k+'='+v).join('; ')}:{})},...(body===undefined?{}:{body:JSON.stringify(body)}),signal:AbortSignal.any([controller.signal,AbortSignal.timeout(180000)])});for(const cookie of r.headers.getSetCookie()){const pair=cookie.split(';')[0],at=pair.indexOf('=');cookies.set(pair.slice(0,at),pair.slice(at+1));}const value={status:r.status,body:await r.json()};return value;}
 const auth=await request('/api/auth/login',{username:user.username,password});assert.equal(auth.status,200);token=auth.body.token;assert(token&&cookies.has('connect.sid'));return request;}
 const ok=async(request,route,body)=>{const value=await request('/api/workshop/csrf'+route,body);assert.equal(value.status,200,route);return value.body;};
 try{const a=await login(student),b=await login(sibling);await ok(a,'/agent-chat-toggle',{tab:'indirect',enabled:true});await ok(b,'/agent-chat-toggle',{tab:'indirect',enabled:true});await ok(b,'/rag/state');
 async function chat(request,user,name,text){const start=transport.calls.length;const value=await ok(request,'/chat',{tab:'indirect',message:text});result.cases.push({name,query:text,response:value,callRange:[start+1,transport.calls.length]});save();assert.equal(value.llmOk,true,'Actual attributable summary required');assert(transport.calls.length>start);const actual=assertActualCalls(transport.calls.slice(start),transport.model);if(value.ragHtml){assert(actual.text.includes(value.ragHtml),'Returned gadget must occur in actual actor bytes');assert(actual.request.messages.some(m=>m.role==='user'&&m.content.includes(value.ragHtml)),'Gadget must come from actual retrieval context');}return value;}
 await chat(b,sibling,'clean-Q1',cohort.queries.first.text);assert.equal((await state(sibling)).indirect.victim.security.mfaEnabled,true);assert.equal((await state(sibling)).indirect.ragFiredQuestions?.length||0,0);assert.equal((await progress.getWorkshopProgress(sibling.id,'csrf_workshop')).completedObjectiveCount,0);const siblingBefore=await evidence.siblingSnapshot();
 await ok(a,'/rag/state');await ok(a,'/rag/poison',{doc:cohort.source.text});await evidence.complete('csrf_i1');
 await chat(a,student,'off-topic',cohort.queries.offTopic.text);assert.equal((await state(student)).indirect.victim.security.mfaEnabled,true);assert.equal((await state(student)).indirect.ragFiredQuestions?.length||0,0);
 await chat(a,student,'on-topic-first',cohort.queries.first.text);await evidence.complete('csrf_i2');assert.deepEqual((await state(student)).indirect.ragFiredQuestions,[cohort.queries.first.normalizedQuerySha256]);
 await chat(a,student,'same-query-replay',cohort.queries.first.text);assert.deepEqual((await state(student)).indirect.ragFiredQuestions,[cohort.queries.first.normalizedQuerySha256]);assert.equal((await progress.getWorkshopProgress(student.id,'csrf_workshop')).completedObjectiveCount,2);
 await chat(a,student,'on-topic-second',cohort.queries.second.text);await evidence.complete('csrf_i3');const hashes=[cohort.queries.first.normalizedQuerySha256,cohort.queries.second.normalizedQuerySha256];assert.deepEqual((await state(student)).indirect.ragFiredQuestions,hashes);
 await ok(a,'/defense-toggle',{tab:'indirect',enabled:true});const defendedBefore=await state(student),activityBefore=await ok(a,'/activity?tab=indirect');const defended=await chat(a,student,'defended-second-query',cohort.queries.second.text);assert(defended.ragHtml,'Defense outcome unproven: no actual preserved gadget reached interpreter');const activityAfter=await ok(a,'/activity?tab=indirect');assertDefendedActivity(activityBefore,activityAfter);assert.deepEqual((await state(student)).indirect.victim,defendedBefore.indirect.victim);assert.deepEqual((await state(student)).indirect.ragFiredQuestions,hashes);assert.equal((await progress.getWorkshopProgress(student.id,'csrf_workshop')).completedObjectiveCount,3);
 const immutable=await evidence.finalSnapshot(),calls=transport.calls.length;await ok(a,'/mode',{mode:'fixed'});for(const [route,body]of [['/rag/poison',{doc:cohort.source.text}],['/chat',{tab:'indirect',message:cohort.queries.first.text}]]){const denied=await a('/api/workshop/csrf'+route,body);assert.equal(denied.status,409);assert.equal(denied.body.code,'CSRF_OBJECTIVE_MODE_UNSUPPORTED');}assert.equal(transport.calls.length,calls);await ok(a,'/mode',{mode:'vuln'});
 const forged=await a('/api/workshop/csrf/progress/complete',{objectiveId:'csrf_i3'});assert.equal(forged.status,409);assert.equal(forged.body.code,'JUDGED_ATTEMPT_REQUIRED');assert.equal(transport.calls.length,calls);
 await ok(a,'/progress/reset-tab',{tab:'indirect'});assert.equal((await progress.getWorkshopProgress(student.id,'csrf_workshop')).completedObjectiveCount,0);assert((await evidence.documents(student)).every(d=>d.retired_at));assert.deepEqual(await evidence.finalSnapshot(),immutable);assert.deepEqual(await evidence.siblingSnapshot(),siblingBefore);
 assert.equal((await a('/api/auth/logout',{})).status,200);const revoked=await a('/api/workshop/csrf/rag/poison',{doc:cohort.source.text});assert([401,403].includes(revoked.status));assert.equal(transport.calls.length,calls);result.status='passed';result.technicalComplete=true;result.acceptedObjectives=['csrf_i1','csrf_i2','csrf_i3'];save();return result;
 }catch(error){result.status='failed';result.technicalComplete=false;result.failure={message:error.message,stack:error.stack};save();throw error;}finally{clearTimeout(timer);controller.abort();}
}
module.exports={runIndirectChain,assertDefendedActivity};
